
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_gga_xc_hcth_147_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("gga_xc_hcth_147", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-4.524027171604144e+00, -4.432395003684575e+00, -4.304115935383154e+00, -4.126681381263432e+00, -3.885501683469539e+00, -3.565915264344774e+00, -3.158054616402557e+00, -2.666441849636889e+00, -2.125608607532465e+00, -1.606884887952130e+00, -1.119642960924743e+00, -7.744565698119900e-01, -6.667077035532513e-01, -5.442661431708917e-01, -3.923289252631592e-01, -2.547389092911748e-01, -1.577882044299051e-01, -7.717756736740396e-02, -1.976703988974534e-02, -2.415672484099013e-03]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


